uuid, 'e452edd7-9421-474e-8064-e8b2d5f2c294'::uuid, 'D) acceleration', FALSE, 3),('51b169a6-7b6d-41f8-83c8-2fed782c9471'::uuid, 'c5581651-7429-4b34-8cc9-07bc63d3e0d3'::uuid, 'A) 5 m/s', TRUE, 0),('bc464b34-81f4-4ef1-8af9-885a250a3cf9'::uuid, 'c5581651-7429-4b34-8cc9-07bc63d3e0d3'::uuid, 'B) 35 m/s', FALSE, 1),('fc5ac04d-d7a1-402d-88b3-ec130d1a53cf'::uuid, 'c5581651-7429-4b34-8cc9-07bc63d3e0d3'::uuid, 'C) 20 m/s', FALSE, 2),('fe5c59f5-185e-4838-823b-8adc2a7491ce'::uuid, 'c5581651-7429-4b34-8cc9-07bc63d3e0d3'::uuid, 'D) -5 m/s', FALSE, 3),('bc4f63a7-ffad-4b01-8fa7-1c75a02d9ac2'::uuid, 'd9e5a8fd-8bab-465f-8879-c2446ecaf058'::uuid, 'True', FALSE, 0),('775d4ad6-7349-4843-8f61-4c46f87a23bf'::uuid, 'd9e5a8fd-8bab-465f-8879-c2446ecaf058'::uuid, 'False', TRUE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('abb24711-b940-4522-8113-9b74736aa977'::uuid, 'Physics', 'Unit 3', 'Molarum Grade 10 — Physics Elasticity and Static Equilibrium of Rigid Body', 'Source-grounded Molarum Grade 10 Physics questions for Elasticity and Static Equilibrium of Rigid Body.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('f6390549-db28-4a05-888c-13167db97e6f'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'A simply supported beam AB of length 3.0 m carries a downward load W = 90 N acting at its midpoint and an additional downward point load P = 20 N located 0.5 m from the left end A. The beam is supported at A and B. Which of the following gives the correct reaction forces at the supports A and B?', 'RA = 61.7 N, RB = 48.3 N', 'Sum of vertical forces: RA+RB = 110 N. Moments about A: RB*3.0 = 90*1.5 + 20*0.5 = 145 → RB ≈ 48.3 N. Then RA ≈ 61.7 N.', 0),('c0684aed-2cfb-4ae1-8c02-cbfac1a4445c'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'true_false', 'In static equilibrium, the sum of moments about any point on the body is zero.', 'True', 'For equilibrium, both the resultant force and the resultant moment must be zero; thus the moments about any chosen point sum to zero.', 1),('16b6abc7-4e02-401e-8084-11157ab1c316'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Which statement best distinguishes elastic deformation from plastic deformation?', 'Elastic deformation is recoverable after removing the load; plastic deformation is permanent.', 'In elasticity, materials return to original shape after unloading; plastic deformation leaves permanent shape change.', 2),('afd99d3f-b39e-4cf5-8e3b-eff3dd276f82'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Which statement correctly defines the Young''s modulus of a material in the elastic region?', 'It is the ratio of stress to strain in the elastic limit.', 'Young''s modulus E = σ/ε in the elastic region; measures stiffness.', 3),('8bedaf58-123b-40a9-890d-65d186bce6e9'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'State the SI unit of density and briefly explain what it represents.', 'kg/m^3 (mass per unit volume)', 'Density is mass per unit volume; the SI unit is kilograms per cubic meter (kg/m^3).', 4),('ccedc06f-71de-4939-8cf4-11c139a683b5'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'Describe the difference between stress and strain.', 'Stress is force per unit area; strain is the fractional change in dimension (deformation) of a body.', 'Stress (σ) is the internal force per area; strain (ε) is the relative deformation ΔL/L or similar measures.', 5),('9c38982b-8e49-4c0f-8cb0-c7265d0b7994'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'A simply supported beam AB of length 5.0 m is supported at A and B. A downward load W = 150 N acts at the midspan (2.5 m from A). A further downward load P = 60 N acts at x = 1.0 m from A. Calculate the reactions at A and B.', 'RA ≈ 123 N, RB ≈ 87 N', 'Sum of forces: RA+RB = 210 N. Moments about A: RB*5.0 = 150*2.5 + 60*1.0 = 435 → RB ≈ 87 N. RA ≈ 210 - 87 = 123 N.', 6),('cd2d795b-a1c5-463b-8ba4-fa0ede52193c'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'A wire of length L = 2.0 m and cross-sectional area A = 1.0×10−4 m^2 is stretched by a force F = 1000 N, producing an extension ΔL = 0.0005 m. Calculate the Young’s modulus E. Provide the method and final unit.', 'E = 4.0×10^10 Pa (40 GPa)', 'Stress σ = F/A = 1000 / 1e-4 = 1e7 Pa. Strain ε = ΔL/L = 0.0005/2.0 = 0.00025. E = σ/ε = 1e7 / 2.5×10^-4 = 4.0×10^10 Pa.', 7),('0580f0b3-d103-4c6a-8692-6e3f8eae2c5a'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Which statement about the stress-strain curve for a material in the elastic region is true?', 'C. Stress is proportional to strain, with a constant slope equal to Young''s modulus.', 'In the elastic region, Hooke''s law holds: σ = Eε; slope equals E.', 8),('9965b46a-5877-4fb7-8056-ba6dfd9c5e2e'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Specific gravity of a substance is defined as the ratio of its density to the density of water at 4°C. What is its unit?', 'dimensionless (no units)', 'Specific gravity is a ratio of densities, so the units cancel; SG is dimensionless.', 9),('32cba497-2e72-4b88-8e65-d45a9d8df841'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'In static equilibrium of a rigid body, which statement is true?', 'The resultant of all external forces on the body is zero.', 'This reflects the First Condition of Equilibrium: the net force on the body must be zero for equilibrium, which also implies no linear acceleration.', 10),('fdccb00f-c306-427c-8726-3e242ba84b36'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Young''s modulus is defined as E = stress divided by strain. Which of the following is the correct statement?', 'Stress divided by strain', 'Young''s modulus relates stress and strain in the elastic region: E = σ/ε. The unit is Pascal (Pa).', 11),('e93a57ce-9893-4a41-8338-27ef42d12f3f'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Elastic limit is defined as the maximum stress that can be applied to a material without causing:', 'Permanent deformation', 'Beyond the elastic limit, permanent (plastic) deformation occurs; within the elastic limit, the material returns to its original shape when the load is removed.', 12),('d2541539-6333-4f2e-81c9-75f5d7502cf6'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'A block has density 7800 kg/m^3 while water has density 1000 kg/m^3. What is its specific gravity (relative to water)?', '7.8', 'Specific gravity is the ratio of the object''s density to the density of water (rho_block / rho_water).', 13),('1f6e36fb-e8e3-41f6-8615-cead5e7ea92a'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'A uniform rod of length 2 m with weight 20 N is hinged at its left end. It is held horizontally by a rope attached to the right end making an angle of 30° above the horizontal. If in equilibrium, what is the tension T in the rope?', '20 N', 'Taking moments about the hinge: T sin(30°) × 2 m = 20 N × 1 m. With sin(30°)=0.5, T × 1 = 20 → T = 20 N.', 14),('b377580a-a41a-4d4d-81ee-3a1c443a3e96'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'true_false', 'The second condition of equilibrium requires that the sum of moments about any point must be zero.', 'True', 'The second condition states that the net moment (torque) about any point is zero for equilibrium.', 15),('b3468ec6-b8e4-4227-8be6-8d255529cb34'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'Explain briefly what is meant by the first condition of equilibrium and give a simple example from a static, rigid-body situation.', 'The first condition requires the vector sum of all forces on the body to be zero, so there is no acceleration. Example: a book at rest on a table, where the upward normal force and downward gravitational force are equal and opposite.', 'The first condition requires the net force to be zero, so the object has no acceleration. In the textbook example of a book at rest on a table, the upward normal force and downward gravitational force are equal in magnitude and opposite in direction, making the net force zero.', 16),('265b5d39-7e3a-497b-897d-764753dded35'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'Define strain and describe the difference between tensile and compressive strain.', 'Strain is the dimensionless fractional change in a body’s length, volume, or geometry caused by stress. Tensile strain is the change in length caused by a longitudinal pulling force; compressive strain is the corresponding shortening under a longitudinal compressing force.', 'Strain is the fractional change in length (ΔL/L0) due to applied stress. Tensile strain stretches the material (ΔL>0); compressive strain shortens it (ΔL<0).', 17),('dcec474c-bb20-45cb-8674-eae24bd22dfe'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'A solid of volume 0.002 m^3 is completely submerged in water. Given water density 1000 kg/m^3 and g = 9.81 m/s^2, calculate the buoyant force on the block. Provide the method and final unit.', 'Buoyant force F_b = ρ_water × g × V_sub = 1000 × 9.81 × 0.002 = 19.62 N', 'Buoyant force equals the weight of the displaced water (Archimedes'' principle). Here V_sub = 0.002 m^3, ρ_water = 1000 kg/m^3, g = 9.81 m/s^2; F_b = 19.62 N.', 18),('f87430d5-0939-4e07-8d9b-f97e3b1b7b62'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'A solid block of volume 0.004 m^3 has density 900 kg/m^3. What is its weight? Provide the method and final unit.', 'Weight W = mg = (ρ × V) × g = (900 kg/m^3 × 0.004 m^3) × 9.81 m/s^2 = 3.6 kg × 9.81 m/s^2 = 35.316 N ≈ 35.3 N', 'Mass m = density × volume; m = 900 × 0.004 = 3.6 kg. Weight W = m g = 3.6 × 9.81 ≈ 35.3 N.', 19),('bc048d0d-9f5d-461d-85bd-392bc2139838'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'In static equilibrium, the vector sum of all forces acting on a rigid body must be what?', 'The resultant force is zero.', 'First condition of equilibrium states that the net force is zero (∑F = 0) for a body to be in equilibrium.', 20),('29b4b66f-3f4f-4530-8ef3-af48cb6af940'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Which option correctly defines Young''s modulus?', 'The ratio of longitudinal stress to longitudinal strain in the elastic region.', 'Young''s modulus E is defined as stress over strain in the elastic (linear) region.', 21),('717d5cd1-50e7-44ba-85c4-338de6c733ba'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Which statement about static equilibrium is true?', 'The resultant force must be zero but moments may be nonzero.', 'A body in static equilibrium has zero net force and zero net moment about any point.', 22),('34551b03-0e7b-47fa-832f-03aa23b76e5f'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'If a rod is stretched within its elastic limit and the applied force is doubled while the cross-sectional area remains constant, what happens to the Young''s modulus (E)?', 'Doubling the force doubles both stress and strain, leaving E unchanged.', 'Within the elastic region, E remains constant for a material; doubling the force increases both stress and strain proportionally, so E stays the same.', 23),('7b7d5cd3-3cbd-4ae1-80d6-7fa236f14c2c'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'true_false', 'For static equilibrium, the sum of moments (torques) about any point must be zero.', 'True', 'Second condition of equilibrium requires zero net torque about any point.', 24),('deda5819-02df-4741-855e-d6a26d4b3da5'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Specific gravity of a liquid is', 'The ratio of the density of the liquid to the density of water at a reference temperature', 'Specific gravity is density divided by density of water at a reference temperature; it is unitless.', 25),('306fa08e-88ce-4ba3-8697-10a94d3ad326'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'Define elastic deformation and plastic deformation.', 'Elastic deformation is a reversible deformation that disappears when the load is removed; plastic deformation is permanent, remaining after removing the load (beyond the elastic limit).', 'Elastic deformation is recoverable; plastic deformation results in permanent shape change after unloading.', 26),('ae086e80-acbd-4af1-8110-c1a2b4256e73'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'State the second condition of equilibrium and describe how you would verify it for a rigid body using torque about a chosen point.', 'The second condition states that the sum of moments (torques) about any axis/point must be zero for equilibrium. To verify, compute the torques of all forces about a chosen point and ensure their algebraic sum is zero; if not, adjust unknowns (e.g., support reactions) until the sum is zero.', 'For a body in equilibrium, both the net force and the net moment are zero; torque balance about any point ensures rotational equilibrium.', 27),('cf2fd4be-da59-429c-8d75-253790cd06db'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'A steel rod of length L = 2.0 m and cross-sectional area A = 1.0e-4 m^2 is stretched by a force F = 500 N along its length. The measured extension ΔL = 0.0005 m. Calculate Young''s modulus E.', '2.0e10 Pa (20 GPa)', 'E = (F/A) / (ΔL/L) = (F L) / (A ΔL) = (500 × 2.0) / (1.0e-4 × 0.0005) = 2.0 × 10^10 Pa = 20 GPa.', 28),('74f1cc94-5549-4413-84e5-876d9f5c412c'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'A uniform beam of length 3.0 m and weight 120 N is simply supported at its ends A and B. The weight acts at the midpoint of the beam. Determine the vertical reaction forces at A and at B.', 'RA = 60 N, RB = 60 N', 'Take moments about A: RB × 3.0 m = 120 N × 1.5 m → RB = 60 N. Then RA = W − RB = 60 N.', 29),('1a238a0e-e5e3-402e-84eb-97414d406e77'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Which statement describes the first condition of equilibrium for a rigid body in static equilibrium?', 'A) The net external force on the body is zero.', 'In static equilibrium, the resultant force must be zero; this is the first condition of equilibrium.', 30),('c1ab4671-bffc-4432-837b-fa3607e974ec'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Young''s modulus is defined as', 'A) stress divided by strain', 'Young''s modulus E = stress/strain; it measures material stiffness.', 31),('a381c82b-9118-4eae-8329-757a32239178'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'A sample with density 900 kg/m^3 has a specific gravity of 0.9. Which of the following represents specific gravity?', 'A) 0.9', 'Specific gravity is the ratio of density to density of water (1000 kg/m^3).', 32),('b992fa45-7dc8-425f-8b0e-16f4695c5695'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'In static equilibrium, which statement is true about torques (moments)?', 'C) Both net force and torque must be zero.', 'The second condition of equilibrium states that the sum of torques about any point must be zero (in addition to net force being zero).', 33),('b745765c-ee1f-4bd1-8933-2ff800c8e9c3'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'multiple_choice', 'Which statement best describes elastic deformation?', 'B) It is reversible; the material returns to its original shape when the load is removed.', 'Elastic deformation is reversible; plastic deformation is permanent.', 34),('d7cf62cd-7f66-402a-8a31-9ed37e4c91c6'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'true_false', 'In static equilibrium, the resultant force must be zero and the resultant torque must also be zero.', 'True', 'Yes. Both net force and net torque must be zero for static equilibrium of a rigid body.', 35),('e466d5bf-db1f-4c86-81c3-565567e2abbf'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'Describe in one sentence the difference between the first and second conditions of equilibrium.', 'First condition: net external force is zero; Second condition: sum of moments (torques) about any point is zero.', 'The first condition ensures no net force; the second ensures no net rotational effect.', 36),('881ad82c-6b86-4fb1-8506-7a7ec254c124'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'Describe, in two to three sentences, how Young''s modulus can be determined experimentally using a wire and measurement of extension under known loads.', 'Use E = (F/A) / (ΔL/L) = (F L) / (A ΔL); apply a known weight F to a wire with cross-sectional area A and length L, measure extension ΔL, then compute E. The resulting unit is Pa (N/m^2).', 'This method uses Hooke''s law for a rod; E relates stress and strain.', 37),('9f472ab2-68be-42e7-843a-889e59f73493'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'A uniform horizontal rod of length 2.0 m weighs 60 N is supported by two vertical ropes at its ends. The left rope has a tension of 30 N. Find the tension in the right rope.', '30 N', 'Sum of vertical forces: T_left + T_right = W; thus T_right = 60 - 30 = 30 N. Taking moments about the left end: T_right * 2.0 m = W * 1.0 m; T_right = 30 N. Both methods yield 30 N.', 38),('8cb677fa-207e-4453-89da-9238b4b0d47b'::uuid, 'abb24711-b940-4522-8113-9b74736aa977'::uuid, 'fill_blank', 'A horizontal beam 6.0 m long is supported at its ends A and B. A 200 N weight acts at 2.0 m from A. Determine the reactions at supports RA and RB.', 'RA = 133.3 N; RB = 66.7 N', 'Take moments about A: RB * 6.0 = 200 * 2.0 => RB = 66.7 N. Then RA = 200 - 66.7 = 133.3 N.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('a6f67074-b9cf-46e6-857a-3d0db527b070'::uuid, 'f6390549-db28-4a05-888c-13167db97e6f'::uuid, 'RA = 61.7 N, RB = 48.3 N', TRUE, 0),('ddd12190-d030-491e-8b5b-5c4dec1083c8'::uuid, 'f6390549-db28-4a05-888c-13167db97e6f'::uuid, 'RA = 48.3 N, RB = 61.7 N', FALSE, 1),('4bca7180-1db2-417b-83d6-8904534bbf4f'::uuid, 'f6390549-db28-4a05-888c-13167db97e6f'::uuid, 'RA = 45.0 N, RB = 66.0 N', FALSE, 2),('58973881-a500-4549-8fe3-541688955878'::uuid, 'f6390549-db28-4a05-888c-13167db97e6f'::uuid, 'RA = 70.0 N, RB = 40.0 N', FALSE, 3),('0d8f0bec-c91f-48c3-8383-e4bbe70c9750'::uuid, 'c0684aed-2cfb-4ae1-8c02-cbfac1a4445c'::uuid, 'True', TRUE, 0),('2a40b0bc-b2a9-4677-8b18-d6efb247b0e1'::uuid, 'c0684aed-2cfb-4ae1-8c02-cbfac1a4445c'::uuid, 'False', FALSE, 1),('009049d8-698c-49ae-8f1b-dcc7d71a50de'::uuid, '16b6abc7-4e02-401e-8084-11157ab1c316'::uuid, 'Elastic deformation is permanent; plastic deformation is recoverable.', FALSE, 0),('acba87be-e151-46ee-8390-b325d4cd814b'::uuid, '16b6abc7-4e02-401e-8084-11157ab1c316'::uuid, 'Elastic deformation is recoverable after removing the load; plastic deformation is permanent.', TRUE, 1),('9646116a-9dd5-493b-83a4-0424b087c009'::uuid, '16b6abc7-4e02-401e-8084-11157ab1c316'::uuid, 'Both are always reversible regardless of load history.', FALSE, 2),('2a41aaf8-425a-4f52-8e30-422ead337164'::uuid, '16b6abc7-4e02-401e-8084-11157ab1c316'::uuid, 'Only plastic deformation occurs under tensile loading.', FALSE, 3),('a365452d-eab7-4a97-8dab-3bd4aa5de32e'::uuid, 'afd99d3f-b39e-4cf5-8e3b-eff3dd276f82'::uuid, 'It is the ratio of strain to stress.', FALSE, 0),('94b2bac5-43b0-4430-8096-5c36f3cda7a1'::uuid, 'afd99d3f-b39e-4cf5-8e3b-eff3dd276f82'::uuid, 'It is the ratio of stress to strain in the elastic limit.', TRUE, 1),('05da12c0-a262-4274-84ab-bdbd32900f1d'::uuid, 'afd99d3f-b39e-4cf5-8e3b-eff3dd276f82'::uuid, 'It is the product of stress and strain.', FALSE, 2),('86f691b7-8732-4627-8bec-0f5c5ca829b7'::uuid, 'afd99d3f-b39e-4cf5-8e3b-eff3dd276f82'::uuid, 'It is the sum of stress and strain.', FALSE, 3),('dfc76094-64b3-4e72-8c6b-a52ff8d858ca'::uuid, '0580f0b3-d103-4c6a-8692-6e3f8eae2c5a'::uuid, 'A. The slope (stiffness) decreases as strain increases.', FALSE, 0),('a48adc85-b589-42bb-8a9b-a0c43ec53607'::uuid, '0580f0b3-d103-4c6a-8692-6e3f8eae2c5a'::uuid, 'B. The stress is independent of strain.', FALSE, 1),('4e1996aa-82eb-46a0-8ae0-a1df85c119c5'::uuid, '0580f0b3-d103-4c6a-8692-6e3f8eae2c5a'::uuid, 'C. Stress is proportional to strain, with a constant slope equal to Young''s modulus.', TRUE, 2),('99589885-c904-41f8-86d5-a54ec01c4f88'::uuid, '0580f0b3-d103-4c6a-8692-6e3f8eae2c5a'::uuid, 'D. The area under the curve is zero.', FALSE, 3),('32abe66d-d843-45db-8ab7-dbf623e729eb'::uuid, '9965b46a-5877-4fb7-8056-ba6dfd9c5e2e'::uuid, 'kg/m^3', FALSE, 0),('991a80c1-e40f-4eb0-8163-125cbb98c5d6'::uuid, '9965b46a-5877-4fb7-8056-ba6dfd9c5e2e'::uuid, 'dimensionless (no units)', TRUE, 1),('45e21b07-a4db-41df-81d8-b69483ac5ff3'::uuid, '9965b46a-5877-4fb7-8056-ba6dfd9c5e2e'::uuid, 'm/s^2', FALSE, 2),('ba72500e-0ea4-4fa2-8483-72a894f2194b'::uuid, '9965b46a-5877-4fb7-8056-ba6dfd9c5e2e'::uuid, 'N/m^3', FALSE, 3),('48ef26c2-62d5-41a1-847e-a056427cd1b8'::uuid, '32cba497-2e72-4b88-8e65-d45a9d8df841'::uuid, 'The resultant of all external forces on the body is zero.', TRUE, 0),('e6953687-0607-4d72-8e87-d56a67eeb5e7'::uuid, '32cba497-2e72-4b88-8e65-d45a9d8df841'::uuid, 'The sum of all external moments on the body is zero.', FALSE, 1),('6c0f4b48-3693-4ff2-8ca2-9c24fea946d8'::uuid, '32cba497-2e72-4b88-8e65-d45a9d8df841'::uuid, 'The velocity of the body is zero at all times.', FALSE, 2),('612a27d5-d344-417c-88a9-bb93088a9a1a'::uuid, '32cba497-2e72-4b88-8e65-d45a9d8df841'::uuid, 'The potential energy of the body is minimized in every configuration.', FALSE, 3),('ae8a7e60-9b42-4e97-8a99-96e3ce95a3a1'::uuid, 'fdccb00f-c306-427c-8726-3e242ba84b36'::uuid, 'Stress divided by strain', TRUE, 0),('00cd3407-f7b6-43db-8eac-19c72ddaf1d9'::uuid, 'fdccb00f-c306-427c-8726-3e242ba84b36'::uuid, 'Strain divided by stress', FALSE, 1),('c41b2678-b9c2-4732-8dfa-bdf8f458e5f6'::uuid, 'fdccb00f-c306-427c-8726-3e242ba84b36'::uuid, 'Force divided by area', FALSE, 2),('38ccba9f-aed5-422d-8808-c61b5d492b84'::uuid, 'fdccb00f-c306-427c-8726-3e242ba84b36'::uuid, 'Area divided by length', FALSE, 3),('998faff6-a94f-4225-8c64-d15496d03d90'::uuid, 'e93a57ce-9893-4a41-8338-27ef42d12f3f'::uuid, 'Permanent deformation', TRUE, 0),('cdf730d9-3297-429a-8383-9ea8c016c028'::uuid, 'e93a57ce-9893-4a41-8338-27ef42d12f3f'::uuid, 'Elastic rebound to a larger shape', FALSE, 1),('82f34186-2320-4be9-864f-016c09be9169'::uuid, 'e93a57ce-9893-4a41-8338-27ef42d12f3f'::uuid, 'Fracture of the material', FALSE, 2),('c81aaa53-9bb3-45e6-853e-db046605eaab'::uuid, 'e93a57ce-9893-4a41-8338-27ef42d12f3f'::uuid, 'Increase in density', FALSE, 3),('3a99c51d-ec1c-470c-8550-fe007ead3d29'::uuid, 'd2541539-6333-4f2e-81c9-75f5d7502cf6'::uuid, '1.0', FALSE, 0),('94adbe45-b19e-4601-889c-75c39b70b607'::uuid, 'd2541539-6333-4f2e-81c9-75f5d7502cf6'::uuid, '7.8', TRUE, 1),('488b83c9-19cf-4154-870d-4e728390df32'::uuid, 'd2541539-6333-4f2e-81c9-75f5d7502cf6'::uuid, '0.78', FALSE, 2),('c51201d1-69a8-4027-8d8c-39c51b712be9'::uuid, 'd2541539-6333-4f2e-81c9-75f5d7502cf6'::uuid, '0.65', FALSE, 3),('f78e553f-5c52-459c-8219-407a9f8fe205'::uuid, '1f6e36fb-e8e3-41f6-8615-cead5e7ea92a'::uuid, '10 N', FALSE, 0),('1f666731-ea46-4b76-8408-8e149ad5ba83'::uuid, '1f6e36fb-e8e3-41f6-8615-cead5e7ea92a'::uuid, '20 N', TRUE, 1),('f62334fb-09ec-4c95-865c-a39a1be16bb2'::uuid, '1f6e36fb-e8e3-41f6-8615-cead5e7ea92a'::uuid, '40 N', FALSE, 2),('cd09a1c9-219d-4e60-86f9-03da52495834'::uuid, '1f6e36fb-e8e3-41f6-8615-cead5e7ea92a'::uuid, '60 N', FALSE, 3),('5531bfba-b8a1-45fd-83f6-1ebf2c48deee'::uuid, 'b377580a-a41a-4d4d-81ee-3a1c443a3e96'::uuid, 'True', TRUE, 0),('c29193e7-c4b8-4f9a-87a1-b9f3d422678d'::uuid, 'b377580a-a41a-4d4d-81ee-3a1c443a3e96'::uuid, 'False', FALSE, 1),('c2d65c6d-180f-4e72-8a9e-76b50c85d5ae'::uuid, 'bc048d0d-9f5d-461d-85bd-392bc2139838'::uuid, 'The resultant force is zero.', TRUE, 0),('8568bb91-b18d-4724-8f53-7fd9cff1d068'::uuid, 'bc048d0d-9f5d-461d-85bd-392bc2139838'::uuid, 'The resultant force is nonzero.', FALSE, 1),('a24c12b8-2a26-4f2e-8ac1-aa04dc788443'::uuid, 'bc048d0d-9f5d-461d-85bd-392bc2139838'::uuid, 'The forces must be parallel.', FALSE, 2),('ef6f9b44-e7ee-4387-8af5-609aeab5bd41'::uuid, 'bc048d0d-9f5d-461d-85bd-392bc2139838'::uuid, 'Forces must pass through the same point.', FALSE, 3),('e5c152af-1245-48af-8fef-49ccab70b416'::uuid, '29b4b66f-3f4f-4530-8ef3-af48cb6af940'::uuid, 'The ratio of longitudinal stress to longitudinal strain in the elastic region.', TRUE, 0),('7d312253-5ff7-4f3d-8233-46a69b6c9799'::uuid, '29b4b66f-3f4f-4530-8ef3-af48cb6af940'::uuid, 'The ratio of longitudinal strain to longitudinal stress in the elastic region.', FALSE, 1),('8b38070b-5524-48af-88de-d4b96baf813b'::uuid, '29b4b66f-3f4f-4530-8ef3-af48cb6af940'::uuid, 'Force divided by the cross-sectional area.', FALSE, 2),('4744d6f9-8cea-4e2c-855b-c0fee359bc3d'::uuid, '29b4b66f-3f4f-4530-8ef3-af48cb6af940'::uuid, 'Mass divided by the volume of the material.', FALSE, 3),('baa4e8c5-2b34-4c85-8195-3fe5409b2cdd'::uuid, '717d5cd1-50e7-44ba-85c4-338de6c733ba'::uuid, 'The resultant force must be zero but moments may be nonzero.', TRUE, 0),('02a3fece-a465-499f-8a74-0bbb8ec4b93b'::uuid, '717d5cd1-50e7-44ba-85c4-338de6c733ba'::uuid, 'The resultant moment must be zero but forces may be nonzero.', FALSE, 1),('49857d9f-1675-43fe-82fb-4ccff1495244'::uuid, '717d5cd1-50e7-44ba-85c4-338de6c733ba'::uuid, 'Both the resultant force and the resultant moment must be zero.', FALSE, 2),('858d14cb-c1b0-4fb2-8850-855352aa36eb'::uuid, '717d5cd1-50e7-44ba-85c4-338de6c733ba'::uuid, 'Both the resultant force and resultant moment can be nonzero.', FALSE, 3),('a5c0830e-754e-459e-8c12-c61496edab8d'::uuid, '34551b03-0e7b-47fa-832f-03aa23b76e5f'::uuid, 'Doubling the force doubles both stress and strain, leaving E unchanged.', TRUE, 0),('ec1136ee-ee98-4cf8-8a30-1d2168c7c4d8'::uuid, '34551b03-0e7b-47fa-832f-03aa23b76e5f'::uuid, 'Doubling the force doubles stress but leaves strain unchanged.', FALSE, 1),('15940466-9812-40a4-8a00-aaf8eaa33618'::uuid, '34551b03-0e7b-47fa-832f-03aa23b76e5f'::uuid, 'Stress remains unchanged and strain doubles.', FALSE, 2),('b81969b5-d078-4b3d-80cb-62e256b4b091'::uuid, '34551b03-0e7b-47fa-832f-03aa23b76e5f'::uuid, 'Doubling both stress and strain would double E.', FALSE, 3),('f81b526d-8abc-4ca4-80a4-303e6f87df10'::uuid, '7b7d5cd3-3cbd-4ae1-80d6-7fa236f14c2c'::uuid, 'True', TRUE, 0),('95824b04-f872-4c51-88ec-d93b43ee4e34'::uuid, '7b7d5cd3-3cbd-4ae1-80d6-7fa236f14c2c'::uuid, 'False', FALSE, 1),('3accb7b2-9993-432e-82d1-3fd9fe56b80b'::uuid, 'deda5819-02df-4741-855e-d6a26d4b3da5'::uuid, 'The density of the liquid', FALSE, 0),('a410f6ff-e8ce-49c9-86cb-7508f6fcfdb0'::uuid, 'deda5819-02df-4741-855e-d6a26d4b3da5'::uuid, 'The ratio of the density of the liquid to the density of water at a reference temperature', TRUE, 1),('7d248467-f328-4cf3-86b4-f5cb69d9f271'::uuid, 'deda5819-02df-4741-855e-d6a26d4b3da5'::uuid, 'The mass of water displaced by the liquid', FALSE, 2),('691f69a2-73ae-4496-8b88-19eb88490963'::uuid, 'deda5819-02df-4741-855e-d6a26d4b3da5'::uuid, 'The ratio of pressure to volume of the liquid', FALSE, 3),('2a46aab7-1261-42de-8c91-290ac18ca035'::uuid, '1a238a0e-e5e3-402e-84eb-97414d406e77'::uuid, 'A) The net external force on the body is zero.', TRUE, 0),('cd2c1c66-6ef1-4a8e-8709-cc5fa65ce566'::uuid, '1a238a0e-e5e3-402e-84eb-97414d406e77'::uuid, 'B) The net external torque about any point is zero.', FALSE, 1),('c78a89a0-43c6-4e94-862f-1457a54fd28a'::uuid, '1a238a0e-e5e3-402e-84eb-97414d406e77'::uuid, 'C) The body must be at rest.', FALSE, 2),('077ade73-a597-40df-85ec-d82bf501f0e9'::uuid, '1a238a0e-e5e3-402e-84eb-97414d406e77'::uuid, 'D) The velocity is constant.', FALSE, 3),('911a64ec-89e7-4fc2-86da-9fda867f8915'::uuid, 'c1ab4671-bffc-4432-837b-fa3607e974ec'::uuid, 'A) stress divided by strain', TRUE, 0),('b34cd10e-29a2-4e00-8c61-ee212f6bbfe4'::uuid, 'c1ab4671-bffc-4432-837b-fa3607e974ec'::uuid, 'B) strain divided by stress', FALSE, 1),('f6ac53bb-f347-48f0-85e8-c0d97dbd34d8'::uuid, 'c1ab4671-bffc-4432-837b-fa3607e974ec'::uuid, 'C) density divided by area', FALSE, 2),('ece62d5e-dc40-4d4c-8655-72f8e067b1a1'::uuid, 'c1ab4671-bffc-4432-837b-fa3607e974ec'::uuid, 'D) energy per unit volume', FALSE, 3),('bfd84358-f619-4299-8b13-78e908bfa2b1'::uuid, 'a381c82b-9118-4eae-8329-757a32239178'::uuid, 'A) 0.9', TRUE, 0),('96e51fee-0a0c-4190-8e92-321adedb1cde'::uuid, 'a381c82b-9118-4eae-8329-757a32239178'::uuid, 'B) 900', FALSE, 1),('4403ded7-ee14-455d-8f50-22114a48c20c'::uuid, 'a381c82b-9118-4eae-8329-757a32239178'::uuid, 'C) 1000', FALSE, 2),('506d71fc-245d-4f5e-8ee4-963185164ce8'::uuid, 'a381c82b-9118-4eae-8329-757a32239178'::uuid, 'D) 1.1', FALSE, 3),('845509f0-4561-418b-818c-8e5953162375'::uuid, 'b992fa45-7dc8-425f-8b0e-16f4695c5695'::uuid, 'A) The net force must be zero.', FALSE, 0),('8c506fe1-207d-4b05-84f5-a196229eaeb2'::uuid, 'b992fa45-7dc8-425f-8b0e-16f4695c5695'::uuid, 'B) The sum of torques about any point must be zero.', FALSE, 1),('f09010ee-6911-4728-8015-28243069ef5d'::uuid, 'b992fa45-7dc8-425f-8b0e-16f4695c5695'::uuid, 'C) Both net force and torque must be zero.', TRUE, 2),('6225b22b-77d4-42dd-825f-dadc0452b8ca'::uuid, 'b992fa45-7dc8-425f-8b0e-16f4695c5695'::uuid, 'D) The body can rotate if the net torque is nonzero.', FALSE, 3),('d3378077-d6c6-4ff6-8958-72ce858066d3'::uuid, 'b745765c-ee1f-4bd1-8933-2ff800c8e9c3'::uuid, 'A) It is permanent and cannot be recovered.', FALSE, 0),('82139d33-3442-458c-8e23-a1e8acc5c90f'::uuid, 'b745765c-ee1f-4bd1-8933-2ff800c8e9c3'::uuid, 'B) It is reversible; the material returns to its original shape when the load is removed.', TRUE, 1),('4454e997-e12e-4913-8c07-7b08448235e1'::uuid, 'b745765c-ee1f-4bd1-8933-2ff800c8e9c3'::uuid, 'C) It only occurs in plastics and ceramics.', FALSE, 2),('47bbe49f-6013-4939-81a0-024931b05d8b'::uuid, 'b745765c-ee1f-4bd1-8933-2ff800c8e9c3'::uuid, 'D) It increases with time under constant load.', FALSE, 3),('17158871-8b78-4879-89e4-4875fb7d27da'::uuid, 'd7cf62cd-7f66-402a-8a31-9ed37e4c91c6'::uuid, 'True', TRUE, 0),('54344a8a-91bc-4d0d-829e-8188f7197241'::uuid, 'd7cf62cd-7f66-402a-8a31-9ed37e4c91c6'::uuid, 'False', FALSE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'Physics', 'Unit 4', 'Molarum Grade 10 — Physics Static and Current Electricity', 'Source-grounded Molarum Grade 10 Physics questions for Static and Current Electricity.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('35367997-cff9-424d-8214-b2f59100c381'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Charge exists in nature as which of the following?', 'Positive and negative charges', 'Charges come in two types: positive and negative; like charges repel, unlike attract.', 0),('41f48df8-e19a-4d7d-852f-c287954c494c'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Which method charges a body by rubbing with another material?', 'Friction', 'Charging by friction occurs when two insulators rub together, transferring charge.', 1),('726098df-2390-4be2-8d81-47dfe6291319'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'An electroscope is used to detect what?', 'Electric charges', 'An electroscope detects the presence and magnitude of static charges by leaf divergence.', 2),('69ffbd62-8169-42e3-828e-75aa37fe2930'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Electrical discharge through air occurs due to what process?', 'Ionization of air', 'Discharge through air happens when air becomes ionized, allowing charge flow.', 3),('0e0ebc34-e169-44e4-8ba9-30931d2faef2'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Ohm''s Law relates V, I, and R by V = I R. If R is constant and voltage doubles, what happens to current?', 'Current doubles', 'I = V/R; with R fixed, doubling V doubles I.', 4),('1160ddaa-1c38-4ed9-8462-6cdec054aa14'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'true_false', 'Inside a conductor in electrostatic equilibrium, the electric field is zero.', 'True', 'In electrostatic equilibrium, charges rearrange to cancel internal electric fields.', 5),('9e022292-a6c1-467b-8e2c-2752acacf08b'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'Where should a voltmeter be connected to measure potential difference across a component?', 'In parallel with the component.', 'A voltmeter measures across the component, so it is connected in parallel.', 6),('81d9c2f8-e4b0-4eec-88b2-f9e7e154d750'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'What is the role of a switch in an electric circuit?', 'To open or close the circuit, controlling current flow.', 'A switch toggles connectivity, turning devices on or off by completing or breaking the circuit.', 7),('9f0c93e8-06c1-407e-83bf-01306725bfd6'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'Two point charges q1 = +3 μC and q2 = -5 μC are separated by r = 0.20 m. Calculate the magnitude of the electrostatic force between them. Use k = 8.99×10^9 N m^2/C^2. Show steps and final unit.', '3.37 N', 'F = k|q1 q2|/r^2 = (8.99×10^9)(3×10^-6)(5×10^-6)/(0.20)^2 = 3.37 N (attractive).', 8),('08773a7a-37fe-40c7-8b11-6115fd749708'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'A 12 V source is connected to a network where R1 = 6 Ω is in series with the parallel combo of R2 = 3 Ω and R3 = 6 Ω. Find the total current drawn from the source.', '1.50 A', 'Parallel of 3 Ω and 6 Ω is (3×6)/(3+6) = 2 Ω. Total R = 6 Ω + 2 Ω = 8 Ω. I = V/R = 12/8 = 1.5 A.', 9),('09427125-791a-43f3-82d1-4f898e48198b'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'According to Ohm''s law, which statement is true?', 'A) The current is directly proportional to the voltage for a given resistance.', 'Ohm''s law is V = IR. For a fixed resistance, current I is proportional to voltage V. The other statements misstate the relationships.', 10),('7273d7ae-be20-4647-8bca-8ad227bb0b4f'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'The direction of the electric field around a positive point charge is:', 'A) toward the charge', 'Electric field lines emanate outward from a positive charge, showing the field direction away from the charge.', 11),('f5973bb5-da09-44a6-85bc-6d0f81aece80'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'In a simple circuit with a battery and a resistor, where should the ammeter be placed to measure current?', 'B) In series with the resistor', 'An ammeter must be in series with the component whose current you want to measure so that the same current flows through both.', 12),('c33b635e-ed28-4dd0-8943-06b734494140'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Two resistors of 6 Ω and 3 Ω are connected in parallel to a 12 V source. What is their equivalent resistance?', 'B) 2 Ω', 'For parallel resistors, 1/R_eq = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2, so R_eq = 2 Ω.', 13),('12bb41ab-1898-4397-8573-27121cefe4f5'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'If you double the distance between two charges, the electrostatic force between them becomes:', 'A) halved', 'Coulomb''s law F ∝ 1/r^2; doubling r makes F decrease by a factor of 4.', 14),('3ba1c43e-420a-4477-8954-e5e5abd68da3'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'true_false', 'An ideal voltmeter should be connected in series with the component whose voltage it is measuring.', 'False', 'A voltmeter should be connected in parallel with the component to measure its voltage without significantly altering the circuit.', 15),('36b1cc55-943f-4ada-83b6-c36dbab8f116'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'State Ohm''s law and define the symbols V, I and R.', 'Ohm''s law states V = IR, where V is the voltage across the element, I is the current through it, and R is the resistance.', 'Ohm''s law relates voltage, current, and resistance; V is voltage, I is current, R is resistance.', 16),('065b31ec-15b1-4877-8a35-e6a7313e7cd4'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'Explain how increasing resistance affects current in a circuit with fixed voltage.', 'Increasing resistance reduces current because I = V/R; for constant V, I decreases as R increases.', 'With a fixed voltage, increasing R lowers the current according to Ohm''s law.', 17),('3a422289-8704-4c15-80c1-69ed14b7bed2'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'A 9 V battery is connected across a 3 Ω resistor. What is the current in the circuit? Show your calculation.', '3 A', 'Using Ohm''s law I = V/R, I = 9 V / 3 Ω = 3 A. Final unit: amperes (A).', 18),('356c97ba-8a67-48e3-8564-f9b7fb809f7f'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'Two resistors, 3 Ω and 6 Ω, are in series with a 12 V supply. What is the current in the circuit? Show your calculation.', '1.33 A', 'Total resistance R = 3 Ω + 6 Ω = 9 Ω. Current I = V / R = 12 V / 9 Ω = 1.33 A (approx).', 19),('a375b308-5eaa-4a04-8d18-26a1133ced8d'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Which method of charging a body involves rubbing two insulating materials together to transfer charge?', 'Charging by friction (rubbing)', 'Charging by friction occurs when two insulators are rubbed together, transferring electrons and producing opposite charges on the objects.', 20),('693fc88b-a09a-436a-8ea6-410c6b3352cc'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Coulomb’s law states that the magnitude of the electrostatic force between two point charges is proportional to the product of the charges and inversely proportional to the square of the distance between them.', 'True', 'Coulomb’s law: F ∝ |q1 q2| / r^2; the force acts along the line joining the charges.', 21),('ae91a8ba-b977-4779-84b4-d2ad7cdbe6db'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'true_false', 'Electrical discharge through air can occur when a large potential difference ionizes the air, creating a conductive path.', 'True', 'Discharge happens when air is ionized by a strong electric field creating a conductive path (spark, ionization).', 22),('57ed8051-71c7-4120-827c-5b42f0f3a96f'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'In a series circuit, the current through each resistor is the same.', 'True', 'In a series circuit the same current flows through all components; voltages add up across components.', 23),('95f8b6c1-fab6-4ba5-85db-3b5e293024cf'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Where should a voltmeter be connected to measure the potential difference across a resistor?', 'In parallel with the resistor', 'Voltmeter has very high resistance and is connected in parallel to the component whose voltage is measured.', 24),('85e4aaec-e0eb-4875-83eb-0e13b5651727'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Two point charges q1=3 μC and q2=-2 μC are separated by r=0.05 m. Using Coulomb’s law, which is the correct magnitude of the electrostatic force (k=9×10^9 N m^2/C^2)?', '21.6 N', 'F = k|q1 q2|/r^2 = 9e9 × (3e-6 × 2e-6) / (0.05)^2 = 0.054 / 0.0025 = 21.6 N. Direction is attractive since charges have opposite signs.', 25),('0f9bf974-d68a-4897-89e8-d467d705e5ae'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'State Ohm’s law and identify what each symbol represents.', 'Ohm''s law: V = IR; V is voltage (potential difference), I is current, R is resistance.', 'Ohm’s law relates the current through a conductor to the voltage and its resistance.', 26),('834fcf2a-1a22-4f12-8121-9042c59ba1c9'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'Explain why an ammeter must be connected in series and a voltmeter in parallel in a circuit.', 'An ammeter is placed in series to measure the current through a component without altering the circuit; a voltmeter is placed in parallel to measure potential difference across a component, while drawing minimal current due to its high resistance.', 'Connecting ammeter in series ensures it measures the through-path current; voltmeter in parallel across component measures potential difference without significantly changing current.', 27),('3e1c0d50-79c4-48d5-8754-efa7de730d0b'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'A resistor of 4 Ω is connected to a 12 V source. Calculate the current flowing through the resistor.', '3 A', 'Using Ohm''s law I = V/R, I = 12 V / 4 Ω = 3 A.', 28),('a30d69ec-b8c8-4340-8dc9-aed644cfc59f'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'Two resistors 6 Ω and 3 Ω are connected in parallel across a 12 V source. Calculate the equivalent resistance of the parallel combination and the total current supplied by the source.', '6 A', 'R_eq = 1 / (1/6 + 1/3) = 1 / (1/6 + 2/6) = 1 / (3/6) = 2 Ω; I_total = 12 V / 2 Ω = 6 A.', 29),('afe0fdad-cef7-45c7-81a9-f2a1a69751f0'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Which method of charging involves transfer of charge by touching two objects together?', 'Conduction', 'Charging by conduction occurs when electrons are transferred through direct contact between objects.', 30),('f876e561-d5df-4467-8276-c867001a970d'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'What causes the leaves of a gold-leaf electroscope to diverge when a charged rod is brought near but not touching?', 'Electrostatic repulsion between like charges', 'The presence of a nearby charged object induces charges on the leaves; like charges repel causing divergence.', 31),('737478e0-7a34-4960-8a72-5b01fb7b7ce2'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'If the distance between two identical charges is doubled, what happens to the electrostatic force between them?', 'It becomes one-quarter', 'Coulomb''s law states F ∝ 1/r^2; doubling r reduces the force to one quarter.', 32),('92a18961-25ce-44d4-8a1a-523d3e5f7f9a'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'Electric field strength at a point is defined as the force experienced by a test charge per unit charge.', 'Force per unit charge', 'E = F/q for a small test charge q; the field strength is the force per unit charge.', 33),('d1b19fa2-73a9-4598-8f69-833db6e54629'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'multiple_choice', 'In a parallel circuit with resistors of 2 Ω, 3 Ω and 6 Ω connected to the same 12 V supply, which resistor carries the largest current?', '2 Ω', 'In parallel, current in each branch is I = V/R. The smallest resistance draws the largest current.', 34),('1bf83f15-a2e4-413d-87fa-9ce9e94cd79d'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'true_false', 'Charging by friction creates new electric charges; charge is not conserved.', 'False', 'Charge is transferred between bodies; total charge is conserved.', 35),('ec40aa61-bd47-4fb8-8622-66794fab2020'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'State Coulomb''s law and describe how the force changes when either charge or distance changes.', 'F = k |q1 q2| / r^2. The force increases with the product of the charges and decreases with the square of the distance.', 'Coulomb''s law relates the electrostatic force between two point charges to the product of the charges and the inverse square of their separation.', 36),('6735c58e-8fe1-406c-8acb-d9d112d44322'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'What is the direction of the electric field inside a conductor at electrostatic equilibrium?', 'Zero', 'In electrostatic equilibrium, charges rearrange so that no net electric field exists inside the conductor.', 37),('4a6a6194-acee-4146-85e1-6d608bcc15c6'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'Two resistors of 4 Ω and 6 Ω are connected in series to a 9 V battery. Find the current in the circuit (show steps and final unit).', '0.9 A', 'R_total = 4 + 6 = 10 Ω; I = V / R_total = 9 V / 10 Ω = 0.9 A.', 38),('9e94a707-5d34-4558-8a13-3248d3274f0a'::uuid, '4e9e6760-6e90-4d90-86d8-3ddbcb319f8b'::uuid, 'fill_blank', 'Three resistors of 2 Ω, 3 Ω, and 6 Ω are connected in parallel across a 12 V source. Find the equivalent resistance and the total current drawn from the source (show steps and final units).', 'R_eq = 1 Ω; I_total = 12 A', '1/R_eq = 1/2 + 1/3 + 1/6 = 1; R_eq = 1 Ω. I_total = V / R_eq = 12 V / 1 Ω = 12 A.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('5a768508-4978-4976-833a-069ccc144a28'::uuid, '35367997-cff9-424d-8214-b2f59100c381'::uuid, 'Positive and negative charges', TRUE, 0),('cf791c24-61da-4088-84cc-2dbe217137c5'::uuid, '35367997-cff9-424d-8214-b2f59100c381'::uuid, 'Only positive charges', FALSE, 1),('95f5d2ee-8525-4196-8579-40ea92ad3e99'::uuid, '35367997-cff9-424d-8214-b2f59100c381'::uuid, 'Neutral charges only', FALSE, 2),('b614d8ef-01f5-4a1c-8072-9e01ad5c49aa'::uuid, '35367997-cff9-424d-8214-b2f59100c381'::uuid, 'Variable charges that change sign', FALSE, 3),('12c10596-e800-4403-8cf5-e04051ad551b'::uuid, '41f48df8-e19a-4d7d-852f-c287954c494c'::uuid, 'Conduction', FALSE, 0),('8cb08170-90b2-49f9-86bb-6abf83e8f3bd'::uuid, '41f48df8-e19a-4d7d-852f-c287954c494c'::uuid, 'Induction', FALSE, 1),('e85ea92a-2f2e-442d-8494-6df6822dcdd9'::uuid, '41f48df8-e19a-4d7d-852f-c287954c494c'::uuid, 'Friction', TRUE, 2),('07e16b99-ef4f-49e8-8a9d-cb78d695db6c'::uuid, '41f48df8-e19a-4d7d-852f-c287954c494c'::uuid, 'Polarization', FALSE, 3),('c89a7a72-211c-46be-8fef-cfff0ba6ea4b'::uuid, '726098df-2390-4be2-8d81-47dfe6291319'::uuid, 'Magnetic fields', FALSE, 0),('d6346d1e-71b1-4643-8ffd-0c9daa643933'::uuid, '726098df-2390-4be2-8d81-47dfe6291319'::uuid, 'Electric charges', TRUE, 1),('4b1bf6e7-a7cb-4de5-8adc-1f29a12b1984'::uuid, '726098df-2390-4be2-8d81-47dfe6291319'::uuid, 'Temperature changes', FALSE, 2),('d15e95b3-9a75-43c0-8ba1-bd8299351783'::uuid, '726098df-2390-4be2-8d81-47dfe6291319'::uuid, 'Humidity', FALSE, 3),('4735914f-02a4-4d46-891a-1a8901c91a83'::uuid, '69ffbd62-8169-42e3-828e-75aa37fe2930'::uuid, 'Conduction of metals', FALSE, 0),('f982d9da-fcdc-48e1-8e26-e1756de56b2d'::uuid, '69ffbd62-8169-42e3-828e-75aa37fe2930'::uuid, 'Ionization of air', TRUE, 1),('e6057d02-1d6e-4ad2-88e9-3d8cca956b06'::uuid, '69ffbd62-8169-42e3-828e-75aa37fe2930'::uuid, 'Friction', FALSE, 2),('9b9b12de-e24e-4528-8c91-5c3bd7a38023'::uuid, '69ffbd62-8169-42e3-828e-75aa37fe2930'::uuid, 'Induction', FALSE, 3),('2811cf9f-5d26-4737-8076-a829175be8cf'::uuid, '0e0ebc34-e169-44e4-8ba9-30931d2faef2'::uuid, 'Current halves', FALSE, 0),('361210f0-3fc6-4099-83ed-90097e8cddec'::uuid, '0e0ebc34-e169-44e4-8ba9-30931d2faef2'::uuid, 'Current doubles', TRUE, 1),('8d7c371c-ad72-4b1c-8f9d-bc80e08a5a5a'::uuid, '0e0ebc34-e169-44e4-8ba9-30931d2faef2'::uuid, 'Current remains the same', FALSE, 2),('23f19544-67dc-4d9b-8026-8a499dff3259'::uuid, '0e0ebc34-e169-44e4-8ba9-30931d2faef2'::uuid, 'Current quadruples', FALSE, 3),('e250bd9c-f2b7-472c-8861-ce2ac1099a20'::uuid, '1160ddaa-1c38-4ed9-8462-6cdec054aa14'::uuid, 'True', TRUE, 0),('13efde6d-8027-4658-8047-312023e7371f'::uuid, '1160ddaa-1c38-4ed9-8462-6cdec054aa14'::uuid, 'False', FALSE, 1),('1669dfdb-5098-4233-8757-68b729b1ad71'::uuid, '09427125-791a-43f3-82d1-4f898e48198b'::uuid, 'A) The current is directly proportional to the voltage for a given resistance.', TRUE, 0),('390c0d6f-0a49-4202-80be-b545cfb04ad7'::uuid, '09427125-791a-43f3-82d1-4f898e48198b'::uuid, 'B) The current is inversely proportional to the voltage for a given resistance.', FALSE, 1),('fe18f8ce-4af7-4e80-8cd7-66e09e73a0e6'::uuid, '09427125-791a-43f3-82d1-4f898e48198b'::uuid, 'C) The voltage is independent of resistance.', FALSE, 2),('9748cc6c-22da-445e-8314-d77dac88046b'::uuid, '09427125-791a-43f3-82d1-4f898e48198b'::uuid, 'D) The resistance is independent of temperature.', FALSE, 3),('3afda458-49e5-425d-8220-243626b396c2'::uuid, '7273d7ae-be20-4647-8bca-8ad227bb0b4f'::uuid, 'A) toward the charge', TRUE, 0),('f1cc422d-c138-4f3b-855d-a64e36afb2f3'::uuid, '7273d7ae-be20-4647-8bca-8ad227bb0b4f'::uuid, 'B) away from the charge', FALSE, 1),('50f93d47-181f-48e4-88f3-fb5c3d09762d'::uuid, '7273d7ae-be20-4647-8bca-8ad227bb0b4f'::uuid, 'C) perpendicular to the radial direction', FALSE, 2),('01dfac37-b6a3-4f9a-86f9-3c6d097fdc9f'::uuid, '7273d7ae-be20-4647-8bca-8ad227bb0b4f'::uuid, 'D) zero.', FALSE, 3),('4f526de6-bdb5-4963-8644-5dbec078