FALSE, 2),('1ca68b9a-4ddd-470a-8cb7-c4ce0a11d1af'::uuid, '99b11bc4-059a-4b78-8cbd-ef176a165fb7'::uuid, 'D 4.48e-5 N/m, attractive', FALSE, 3),('f6043364-d89d-4bef-8284-aa3e5427ec95'::uuid, '0d88749e-3944-4884-8eb7-e50bd34c02b1'::uuid, 'Each piece has a North Pole only', FALSE, 0),('f72ba6f1-89b6-4fd6-8301-8e95dd7200ec'::uuid, '0d88749e-3944-4884-8eb7-e50bd34c02b1'::uuid, 'Each piece has a North Pole and a South Pole', TRUE, 1),('d36c38ab-ba88-4698-876e-203e0c3de8b5'::uuid, '0d88749e-3944-4884-8eb7-e50bd34c02b1'::uuid, 'All pieces lose magnetism', FALSE, 2),('32ec5619-973d-41cc-8cbd-d17e9244aec0'::uuid, '0d88749e-3944-4884-8eb7-e50bd34c02b1'::uuid, 'One piece becomes a magnet and the other loses magnetism', FALSE, 3),('4fd6f6d4-705c-47a8-88fc-78144ed94c5f'::uuid, '1e9b4d35-4e74-4bd4-8439-53220940ec4c'::uuid, 'The direction and strength of the magnetic force', TRUE, 0),('1cb2e4be-a9cd-42a6-8ede-fa9e3e9373b0'::uuid, '1e9b4d35-4e74-4bd4-8439-53220940ec4c'::uuid, 'The distribution of electric charge', FALSE, 1),('e1c5ba6d-0576-41d0-8dc4-644b8811a582'::uuid, '1e9b4d35-4e74-4bd4-8439-53220940ec4c'::uuid, 'The temperature distribution around the magnet', FALSE, 2),('b57c4d06-7ab4-4d6b-8d07-63045e4ee4bd'::uuid, '1e9b4d35-4e74-4bd4-8439-53220940ec4c'::uuid, 'The path of the magnet’s motion in a field', FALSE, 3),('682d6310-5729-4ba5-8902-06f5dfffa92a'::uuid, 'be68fe6e-2fe4-4506-860f-608c1ae06c8f'::uuid, 'Thermometer', FALSE, 0),('7addf9ca-866d-4845-8fa8-c443576898ca'::uuid, 'be68fe6e-2fe4-4506-860f-608c1ae06c8f'::uuid, 'Barometer', FALSE, 1),('6bb002c2-ceaa-4028-8f82-a40f80e5f99e'::uuid, 'be68fe6e-2fe4-4506-860f-608c1ae06c8f'::uuid, 'Compass', TRUE, 2),('e9fc1949-301c-4417-83b5-a896d43f8eea'::uuid, 'be68fe6e-2fe4-4506-860f-608c1ae06c8f'::uuid, 'Ruler', FALSE, 3),('e4c35b12-459e-46ff-8379-e0bde8f50bc7'::uuid, '13e683ce-0fb1-49d5-8d79-52df9c48a238'::uuid, 'Straight lines parallel to the wire', FALSE, 0),('b3321402-b6aa-4ee9-80d1-a7a0b7d361ee'::uuid, '13e683ce-0fb1-49d5-8d79-52d